'use strict';
const $ = id => document.getElementById(id);
const format = n => new Intl.NumberFormat('ru-RU', {maximumFractionDigits:2}).format(n);
const STORAGE = 'ishod-demo-v1';
let state = {balance:10000, positions:{yes:0,no:0}, saved:false};
try { const cached=JSON.parse(localStorage.getItem(STORAGE)); if(cached && Number.isFinite(cached.balance) && cached.balance>=0 && ['yes','no'].every(s=>Number.isFinite(cached.positions?.[s])&&cached.positions[s]>=0)) state={...state,...cached}; } catch {}
let side='yes', mode='buy', period='ВСЁ', toastTimer;
const prices={yes:64,no:36};
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(state));}catch{}};
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function render(){const price=prices[side];const amount=Number($('amount').value)||0;const shares=Math.floor((amount/price+1e-9)*100)/100;$('balance').textContent=format(state.balance);$('availableBalance').textContent=mode==='buy'?`Доступно ${format(state.balance)} Б`:`Доступно ${format(state.positions[side])} долей`;$('shares').textContent=format(shares);$('payout').textContent=`${format(mode==='buy'?shares*100:shares*price)} Б`;$('returnLabel').textContent=mode==='buy'?'Выплата при выигрыше':'Вы получите';$('submitTrade').innerHTML=`${mode==='buy'?'Купить':'Продать'} ${side==='yes'?'Да':'Нет'}<svg><use href="#arrow"/></svg>`;$('yesButton').className=`side-button${side==='yes'?' active-yes':''}`;$('noButton').className=`side-button${side==='no'?' active-no':''}`;$('yesButton').setAttribute('aria-pressed',String(side==='yes'));$('noButton').setAttribute('aria-pressed',String(side==='no'));$('buyTab').classList.toggle('active',mode==='buy');$('sellTab').classList.toggle('active',mode==='sell');$('buyTab').setAttribute('aria-selected',String(mode==='buy'));$('sellTab').setAttribute('aria-selected',String(mode==='sell'));$('bookmarkButton').setAttribute('aria-pressed',String(state.saved));$('tradeError').hidden=true;}
function chooseSide(s){side=s;render();}
$('yesButton').onclick=()=>chooseSide('yes');$('noButton').onclick=()=>chooseSide('no');$('amount').oninput=render;
$('buyTab').onclick=()=>{mode='buy';render();};$('sellTab').onclick=()=>{mode='sell';render();};
document.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{mode='buy';chooseSide(b.dataset.side);document.querySelector('.trade-card').scrollIntoView({behavior:'smooth',block:'center'});$('amount').focus({preventScroll:true});});
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{$('amount').value=(Number($('amount').value)||0)+Number(b.dataset.add);render();});
$('maxAmount').onclick=()=>{$('amount').value=mode==='buy'?state.balance:Math.round(state.positions[side]*prices[side]*100)/100;render();};
$('submitTrade').onclick=()=>{const amount=Number($('amount').value), price=prices[side];let error='';if(!Number.isFinite(amount)||amount<=0)error='Введите сумму больше нуля.';else if(amount>100000000)error='Сумма превышает доступный баланс.';else if(mode==='buy'&&amount>state.balance+0.00001)error='Недостаточно виртуальных баллов.';let shares=Math.floor((amount/price+1e-9)*100)/100;if(!error&&shares<0.01)error=`Минимальная сумма — ${format(price/100)} Б.`;if(!error&&mode==='sell'&&shares>state.positions[side]+0.000001)error='У вас недостаточно долей этого исхода.';if(error){$('tradeError').textContent=error;$('tradeError').hidden=false;return;}const cost=Math.round(shares*price*100)/100;if(mode==='buy'){state.balance=Math.round((state.balance-cost)*100)/100;state.positions[side]=Math.round((state.positions[side]+shares)*100)/100;}else{state.balance=Math.round((state.balance+cost)*100)/100;state.positions[side]=Math.round((state.positions[side]-shares)*100)/100;}save();$('amount').value='';render();toast(`${mode==='buy'?'Куплено':'Продано'} ${format(shares)} долей «${side==='yes'?'Да':'Нет'}» за ${format(cost)} Б`);};
$('bookmarkButton').onclick=()=>{state.saved=!state.saved;save();render();toast(state.saved?'Событие сохранено':'Событие удалено из сохранённых');};
function showTab(which){const rules=which==='rules';$('rulesContent').hidden=!rules;$('aboutContent').hidden=rules;$('rulesTab').classList.toggle('active',rules);$('aboutTab').classList.toggle('active',!rules);$('rulesTab').setAttribute('aria-selected',String(rules));$('aboutTab').setAttribute('aria-selected',String(!rules));}
$('rulesTab').onclick=()=>showTab('rules');$('aboutTab').onclick=()=>showTab('about');$('howButton').onclick=()=>{showTab('about');$('aboutContent').scrollIntoView({behavior:'smooth',block:'center'});};
function portfolio(){$('dialogBalance').textContent=`${format(state.balance)} Б`;let html='';for(const s of ['yes','no'])if(state.positions[s]>0)html+=`<div class="position"><strong>Новая станция метро в Петербурге · ${s==='yes'?'Да':'Нет'}</strong><div><span>${format(state.positions[s])} долей</span><span>${format(state.positions[s]*prices[s])} Б</span></div><button data-sell="${s}">Продать доли →</button></div>`;$('positions').innerHTML=html||'<div class="portfolio-empty">Здесь появятся ваши доли.<br>Выберите исход и совершите первую пробную покупку.</div>';$('positions').querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>{$('portfolioDialog').close();mode='sell';chooseSide(b.dataset.sell);$('maxAmount').click();document.querySelector('.trade-card').scrollIntoView({behavior:'smooth',block:'center'});});$('portfolioDialog').showModal();}
for(const id of ['portfolioNav','balanceButton','profileButton'])$(id).onclick=portfolio;
$('closeDialog').onclick=()=>$('portfolioDialog').close();$('portfolioDialog').onclick=e=>{if(e.target===$('portfolioDialog')){const r=$('portfolioDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('portfolioDialog').close();}};
for(const id of ['marketsNav','allMarkets','backMarkets'])$(id).onclick=()=>{window.scrollTo({top:0,behavior:'smooth'});toast('Пока доступно одно тестовое событие');};
$('searchInput').oninput=()=>{const q=$('searchInput').value.trim().toLowerCase();$('searchResults').hidden=!q;if(q)$('searchResults').innerHTML=/метро|петер|станц|город|2026|откро|нов/.test(q)?'<button id="searchEvent">🚇 Откроют ли новую станцию метро в Петербурге до конца 2026 года?</button>':'Других событий пока нет';const b=$('searchEvent');if(b)b.onclick=()=>{$('searchResults').hidden=true;$('searchInput').value='';$('chartContainer').scrollIntoView({behavior:'smooth',block:'center'});};};
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('searchResults').hidden=true;});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('searchInput').focus();}if(e.key==='Escape')$('searchResults').hidden=true;});
// Seeded, illustrative prices. No external market data is used.
let seed=42;const random=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646;};
const anchors=[48,51,47,50,43,46,44,52,49,53,58,55,59,56,61,58,63,60,58,63,61,68,64,66,64];
const history=[];for(let a=0;a<anchors.length-1;a++)for(let j=0;j<10;j++){const t=j/10;history.push(Math.max(5,Math.min(95,anchors[a]*(1-t)+anchors[a+1]*t+(random()-.5)*3)));}history.push(64);
let visible=[];
function drawChart(){const sizes={'1Д':24,'1Н':60,'1М':110,'3М':180,'ВСЁ':history.length};visible=history.slice(-sizes[period]);const w=880,h=300,left=0,right=785,top=16,bottom=260;const x=i=>left+i/(visible.length-1)*(right-left);const y=v=>bottom-v/100*(bottom-top);const path=values=>values.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(2)},${y(v).toFixed(2)}`).join(' ');const yes=path(visible),no=path(visible.map(v=>100-v));let svg=`<defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#427dff" stop-opacity=".16"/><stop offset="100%" stop-color="#427dff" stop-opacity="0"/></linearGradient></defs>`;for(const v of [0,25,50,75,100])svg+=`<line class="grid-line" x1="0" x2="832" y1="${y(v)}" y2="${y(v)}"/><text class="axis-label" x="845" y="${y(v)+4}">${v}%</text>`;svg+=`<path d="${yes} L${right},${bottom} L0,${bottom} Z" fill="url(#area)"/><path class="no-line" d="${no}"/><path class="yes-line" d="${yes}"/><circle cx="${right}" cy="${y(64)}" r="11" fill="#4377ff" opacity=".15"/><circle cx="${right}" cy="${y(64)}" r="4" fill="#8fb8ff"/><text x="800" y="${y(64)+4}" fill="#91b8ff" font-size="12" font-family="inherit">64</text><circle cx="${right}" cy="${y(36)}" r="3" fill="#7c729d"/><text x="800" y="${y(36)+4}" fill="#7c729d" font-size="12" font-family="inherit">36</text>`;const labels={'1Д':['00:00','04:00','08:00','12:00','16:00','20:00'],'1Н':['19 окт.','20 окт.','21 окт.','22 окт.','23 окт.','25 окт.'],'1М':['25 сент.','1 окт.','7 окт.','13 окт.','19 окт.','25 окт.'],'3М':['25 июля','12 авг.','30 авг.','18 сент.','6 окт.','25 окт.'],'ВСЁ':['МАЙ','ИЮНЬ','ИЮЛЬ','АВГ.','СЕНТ.','ОКТ.']};labels[period].forEach((label,i)=>{svg+=`<text class="axis-label" x="${i/5*right}" y="290" text-anchor="${i===0?'start':i===5?'end':'middle'}">${label}</text>`;});svg+='<line id="crosshair" x1="0" x2="0" y1="16" y2="260" stroke="#748aaa" stroke-dasharray="3 4" opacity="0"/><circle id="hoverDot" r="4" fill="#c3d8ff" opacity="0"/>';$('chart').innerHTML=svg;document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('selected',b.dataset.period===period));}
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;drawChart();});
$('chartContainer').onpointermove=e=>{const r=$('chart').getBoundingClientRect();const px=(e.clientX-r.left)/r.width*880;const index=Math.max(0,Math.min(visible.length-1,Math.round(px/785*(visible.length-1))));const value=visible[index],cx=index/(visible.length-1)*785,cy=260-value/100*244;$('crosshair').setAttribute('x1',cx);$('crosshair').setAttribute('x2',cx);$('crosshair').setAttribute('opacity','1');$('hoverDot').setAttribute('cx',cx);$('hoverDot').setAttribute('cy',cy);$('hoverDot').setAttribute('opacity','1');const tip=$('chartTooltip');tip.textContent=`Да ${Math.round(value)}% · Нет ${100-Math.round(value)}%`;tip.hidden=false;tip.style.left=`${Math.max(0,Math.min(e.clientX-r.left-65,r.width-150))}px`;tip.style.top='8px';};
$('chartContainer').onpointerleave=()=>{$('chartTooltip').hidden=true;$('crosshair')?.setAttribute('opacity','0');$('hoverDot')?.setAttribute('opacity','0');};
render();drawChart();
